200	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
201	public record ReservationReceipt(
202	        String title,
203	        long reservationId,
204	        String guestName,
205	        String guestCpf,
206	        int roomNumber,
207	        RoomType roomType,
208	        LocalDate checkIn,
209	        LocalDate checkOut,
210	        int nights,
211	        BigDecimal subtotal,
212	        BigDecimal discount,
213	        BigDecimal total) {
214	
215	    public ReservationReceipt(Reservation reservation, Room room) {
216	        this(
217	                "Comprovante de reserva",
218	                reservation.id(),
219	                reservation.guest().name(),
220	                reservation.guest().cpf(),
221	                room.number(),
222	                room.type(),
223	                reservation.checkIn(),
224	                reservation.checkOut(),
225	                reservation.price().nights(),
226	                reservation.price().subtotal(),
227	                reservation.price().discount(),
228	                reservation.price().total());
229	    }
230	
231	    public String text() {
232	        StringBuilder text = new StringBuilder();
233	        text.append(title).append(" nº ").append(reservationId).append('\n');
234	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
235	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
236	        text.append("Entrada: ").append(TextFormat.date(checkIn))
237	                .append(" | Saída: ").append(TextFormat.date(checkOut))
238	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
239	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
240	        if (discount.signum() > 0) {
241	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
242	        }
243	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
244	        return text.toString();
245	    }
246	}
