250	import java.time.LocalDate;
251	import java.time.format.DateTimeFormatter;
252	import java.util.Locale;
253	
254	/** How money and dates are written in the texts the guest reads (Brazilian Portuguese). */
255	public final class TextFormat {
256	
257	    private static final Locale BRAZIL = Locale.forLanguageTag("pt-BR");
258	    private static final DateTimeFormatter BRAZILIAN_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
259	
260	    private TextFormat() {
261	    }
262	
263	    public static String money(BigDecimal amount) {
264	        return "R$ " + String.format(BRAZIL, "%,.2f", amount);
265	    }
266	
267	    public static String date(LocalDate date) {
268	        return BRAZILIAN_DATE.format(date);
269	    }
270	}

